    "shortDescription": "문화 유적지, 산간 지대의 풍경, 야생동물, 그리고 남부 해변을 아우르는 17일 16박의 여정.",
    "overview": "하바라나, 시기리야, 히리와둔나, 미네리야를 둘러보며 열기구 체험과 아누라다푸라 방문을 즐겨보세요. 담불라 동굴 사원, 캔디의 불치사, 문화 공연, 암불루와와 탑, 왕립 식물원을 탐방해 보세요. 누와라 엘리야를 거쳐 람보다 폭포, 그레고리 호수, 딸기 농장을 둘러본 뒤, 엘라로 이동해 나인 아치 브리지, 미니 아담스 피크, 라바나 폭포를 감상하세요. 남부 구간에서는 얄라 국립공원, 미리사, 갈레 네덜란드 요새, 코스고다 바다거북 부화장, 벤토타 일몰 크루즈를 즐길 수 있습니다. 마지막으로 콜롬보 시내 관광, 쇼핑, 길거리 음식을 즐기며 일정을 마무리합니다.",
