    "shortDescription": "네곰보, 하바라나, 캔디, 누와라 엘리야, 엘라를 거쳐 12일 11박을 보낸 뒤, 갈레와 콜롬보를 경유해 돌아왔다.",
    "overview": "미네리야 야생동물 관찰과 히리와둔나 마을, 시기리야, 열기구 체험, 담불라 동굴 사원을 함께 둘러보세요. 캔디에서는 불치사(Temple of the Tooth)와 암불루와와 탑을 방문하고 문화 공연을 감상해 보세요. 이어 차 공장과 엘라의 명소인 나인 아치 브리지, 미니 아담스 피크, 라바나 폭포를 둘러보세요. 콜롬보 시내 관광과 쇼핑을 즐기기 전에 갈레 네덜란드 요새를 방문하세요.",
